<template><view class="page"><view v-if="card" class="card"><text class="progress">学习进度 {{ card.progress.completed }} / {{ card.progress.required }} 次有效回忆</text><text class="question">{{ card.question }}</text><button v-if="!showAnswer" @click="showAnswer=true">显示答案</button><view v-else><view v-if="card.aiSummary" class="summary"><text v-for="line in summaryLines" :key="line">{{ line }}</text></view><view class="points"><text v-for="point in keyPoints" :key="point">{{ point }}</text></view><view class="actions"><button @click="rate('again')">重来</button><button @click="rate('hard')">困难</button><button @click="rate('good')">良好</button><button @click="rate('easy')">简单</button></view></view></view><view v-else class="empty">暂无待复习卡片，明天再来看看。</view></view></template>
<script setup>
import { computed, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { getNextReviewCard, rateReviewCard } from '@/api/exam/review';
const card=ref(null), showAnswer=ref(false);
const summaryLines = computed(() => String(card.value?.aiSummary || '').split(/(?=结论：|要点：|补充：)/).filter(Boolean)); const keyPoints = computed(() => String(card.value?.keyPoints || '').split('；').filter(Boolean));
async function load(){card.value=(await getNextReviewCard()).data||null;showAnswer.value=false} async function rate(value){await rateReviewCard(card.value.cardId,value);await load()} onShow(()=>load().catch(()=>{}));
</script>
<style scoped>.page{min-height:100vh;background:#f5f7fb;padding:28rpx 30rpx}.card,.empty{background:#fff;border-radius:22rpx;padding:30rpx}.progress{display:block;color:#748198;font-size:22rpx;margin-bottom:22rpx}.question{display:block;color:#25324a;line-height:1.6;margin-bottom:30rpx;font-size:34rpx;font-weight:700}.summary{margin-top:24rpx}.summary text{display:block;color:#344158;font-size:25rpx;line-height:1.8;margin-bottom:14rpx}.points{display:flex;flex-wrap:wrap;gap:12rpx;margin-top:24rpx}.points text{padding:10rpx 16rpx;border-radius:10rpx;background:#e8f3ff;color:#3b78aa;font-size:22rpx}.actions{display:flex;gap:10rpx;margin-top:26rpx}.actions button{flex:1;font-size:22rpx}.empty{text-align:center;color:#8b96a8;margin-top:24rpx}</style>
